{
  "requirement_id": "REQ-006",
  "cases": [
    {
      "id": "TC-1",
      "title": "Assign task to non-project member",
      "surface": "api",
      "steps": [
        "POST /api/projects with name 'Project A' as alice",
        "POST /api/projects/{pid}/tasks with title 'Task 1' as alice",
        "PATCH /api/tasks/{tid} with body {\"assignee_id\": 999} where 999 is a user who is not a member of Project A, as alice"
      ],
      "expected": "指派對象必須是該專案成員；否則回傳 422 狀態碼，且任務的 assignee 維持不變。"
    },
    {
      "id": "TC-2",
      "title": "Assign task to non-existent user",
      "surface": "api",
      "steps": [
        "POST /api/projects with name 'Project B' as alice",
        "POST /api/projects/{pid}/tasks with title 'Task 1' as alice",
        "PATCH /api/tasks/{tid} with body {\"assignee_id\": 88888} where 88888 does not exist in the system, as alice"
      ],
      "expected": "指派不存在的使用者時，回傳 422 狀態碼。"
    }
  ]
}

